import { TaskRepository } from '../domain/TaskRepository';
import { UserRepository } from '../domain/UserRepository';
import { AssignTaskRequest, AssignTaskResponse } from './dtos';

export class AssignTaskUseCase {
  constructor(
    private taskRepository: TaskRepository,
    private userRepository: UserRepository,
  ) {}

  execute(request: AssignTaskRequest): AssignTaskResponse {
    const task = this.taskRepository.findById(request.taskId);
    if (!task) {
      throw new Error('Task not found');
    }

    const user = this.userRepository.findById(request.userId);
    if (!user) {
      throw new Error('User not found');
    }

    task.assignToUser(request.userId);
    this.taskRepository.save(task);

    return {
      id: task.id,
      projectId: task.projectId,
      title: task.title,
      description: task.description,
      dueDate: task.dueDate,
      status: task.status,
      assignedToUserId: task.assignedToUserId,
    };
  }
}

